import{RIVERS,FISH_TYPES,OBSTACLE_TYPES,LANDMARKS}from"./river-data.js";export class RiverEngine{constructor(t,s){this.width=t,this.height=s,this.riverBaseSpeed=3,this.rivers=RIVERS,this.resetState()}resetState(){this.state={river:this.rivers[0],boat:{x:this.width/2,y:this.height-100,size:40,speed:5,health:3},distance:0,score:0,fishCount:0,badges:[],entities:[],gameOver:!1,paused:!0},this.spawnTimer=0,this.lastTime=performance.now()}setRiver(t){this.state.river=this.rivers[t]}start(){this.state.paused=!1,this.lastTime=performance.now()}moveBoat(t){if(this.state.gameOver||this.state.paused)return;let s=this.state.boat.x+t*this.state.boat.speed;s>20&&s<this.width-60&&(this.state.boat.x=s)}update(t){if(this.state.gameOver||this.state.paused)return;const s=(t-this.lastTime)/1e3;this.lastTime=t;const e=this.riverBaseSpeed+.05*this.state.distance*this.state.river.difficulty;this.state.distance+=.01*e,this.state.score+=.05*e,this.state.entities.forEach(t=>{t.y+=e}),this.state.entities=this.state.entities.filter(t=>t.y<this.height+50),this.spawnTimer-=s,this.spawnTimer<=0&&(this.spawnEntity(),this.spawnTimer=Math.max(.5,1.5-.02*this.state.distance)),this.checkCollisions(),this.checkBadges(),this.state.boat.health<=0&&(this.state.gameOver=!0,this.state.paused=!0)}spawnEntity(){const t=Math.random()*(this.width-100)+50,s=Math.random();let e={x:t,y:-50,size:40,active:!0};if(s<.5){const t=OBSTACLE_TYPES[Math.floor(Math.random()*OBSTACLE_TYPES.length)];e.type="obstacle",e.icon=t.icon,e.damage=t.damage,e.points=t.points}else if(s<.9){const t=FISH_TYPES[Math.floor(Math.random()*FISH_TYPES.length)];e.type="fish",e.icon=t.icon,e.points=t.points}else{const t=LANDMARKS[Math.floor(Math.random()*LANDMARKS.length)];e.type="landmark",e.icon=t.icon,e.name=t.name,e.badge=t.badge,e.points=200}this.state.entities.push(e)}checkCollisions(){const t=this.state.boat,s=.8*t.size;this.state.entities.forEach(e=>{e.active&&t.x<e.x+s&&t.x+s>e.x&&t.y<e.y+s&&t.y+s>e.y&&(e.active=!1,"obstacle"===e.type?(this.state.boat.health-=e.damage,this.state.score+=e.points):"fish"===e.type?(this.state.score+=e.points,this.state.fishCount++):"landmark"===e.type&&(this.state.score+=e.points,this.state.badges.includes(e.badge)||(this.state.badges.push(e.badge),this.state.score+=500)))})}checkBadges(){this.state.fishCount>=5&&!this.state.badges.includes("River Biologist")&&(this.state.badges.push("River Biologist"),this.state.score+=500),this.state.distance>=10&&!this.state.badges.includes("Explorer")&&(this.state.badges.push("Explorer"),this.state.score+=500),this.state.score>=1e3&&!this.state.badges.includes("River Legend")&&this.state.badges.push("River Legend")}}